    fn the_liveness_log_path_prefers_the_rounds_artifact_dir() {
        // The launcher exports HOH_ARTIFACT_DIR; when it is there the record must
        // land under that directory's `deterministic/raw/`, and when it is not
        // the working-directory-relative path is used.  The liveness evidence of
