            liveness_log_path(None),
            std::path::Path::new(".hoh/deterministic/raw/liveness.log")
        );
        assert_eq!(
            liveness_log_path(Some("")),
            std::path::Path::new(".hoh/deterministic/raw/liveness.log"),
            "an empty variable is the same as an unset one"
        );
    }

''' + anchor
